import React, { useState } from 'react';
import { useQuery, useMutation, gql } from '@apollo/client';

const LOGIN_USER = gql`
  mutation Login($email: String!, $password: String!) {
    login(email: $email, password: $password) {
      id
      email
    }
  }
`;

const GET_TODOS = gql`
  query GetTodos($userId: ID!) {
    getTodos(userId: $userId) {
      id
      text
      completed
    }
  }
`;

const CREATE_TODO = gql`
  mutation CreateTodo($userId: ID!, $text: String!) {
    createTodo(userId: $userId, text: $text) {
      id
      text
      completed
    }
  }
`;

const DELETE_TODO = gql`
  mutation DeleteTodo($id: ID!) {
    deleteTodo(id: $id)
  }
`;

export default function App() {
  const [user, setUser] = useState(null);
  const [email, setEmail] = useState('test@test.com');
  const [password, setPassword] = useState('password123');
  const [errorMsg, setErrorMsg] = useState('');

  const [login] = useMutation(LOGIN_USER);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      setErrorMsg('');
      const { data } = await login({ variables: { email, password } });
      setUser(data.login);
    } catch (err) {
      setErrorMsg(err.message);
    }
  };

  if (!user) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4">
        <div className="max-w-md w-full bg-white rounded-xl shadow-lg p-8 border border-slate-100">
          <div className="text-center mb-8">
            <h1 className="text-2xl font-bold text-slate-800">Welcome Back</h1>
            <p className="text-slate-500 text-sm mt-1">Sign in to access your task dashboard</p>
          </div>
          {errorMsg && (
            <div className="mb-4 p-3 bg-red-50 border border-red-200 text-red-600 text-sm rounded-lg">
              {errorMsg}
            </div>
          )}
          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-1">Email Address</label>
              <input 
                type="email" 
                value={email} 
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none text-slate-700"
                required
              />
            </div>
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-slate-600 mb-1">Password</label>
              <input 
                type="password" 
                value={password} 
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-4 py-2 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none text-slate-700"
                required
              />
            </div>
            <button 
              type="submit"
              className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition duration-200 shadow-sm"
            >
              Sign In
            </button>
          </form>
          <div className="mt-6 text-center text-xs text-slate-400">
            Hint: Use <span className="font-mono text-slate-600">test@test.com</span> / <span className="font-mono text-slate-600">password123</span>
          </div>
        </div>
      </div>
    );
  }

  return <TodoDashboard user={user} onLogout={() => setUser(null)} />;
}

function TodoDashboard({ user, onLogout }) {
  const [taskText, setTaskText] = useState('');
  const { data, refetch } = useQuery(GET_TODOS, { variables: { userId: user.id } });
  const [createTodo] = useMutation(CREATE_TODO);
  const [deleteTodo] = useMutation(DELETE_TODO);

  const handleAddTodo = async (e) => {
    e.preventDefault();
    if (!taskText.trim()) return;
    await createTodo({ variables: { userId: user.id, text: taskText } });
    setTaskText('');
    refetch();
  };

  const handleDeleteTodo = async (id) => {
    await deleteTodo({ variables: { id } });
    refetch();
  };

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-4">
      <div className="max-w-xl mx-auto">
        <div className="flex justify-between items-center bg-white p-6 rounded-xl shadow-sm border border-slate-100 mb-6">
          <div>
            <h1 className="text-xl font-bold text-slate-800">My Task Dashboard</h1>
            <p className="text-xs text-slate-500 mt-0.5">Logged in as: <span className="font-medium text-slate-700">{user.email}</span></p>
          </div>
          <button 
            onClick={onLogout}
            className="px-4 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg transition duration-150 border border-transparent hover:border-red-100"
          >
            Logout
          </button>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 mb-6">
          <form onSubmit={handleAddTodo} className="flex gap-3">
            <input 
              type="text" 
              placeholder="What needs to be done?" 
              value={taskText}
              onChange={(e) => setTaskText(e.target.value)}
              className="flex-1 px-4 py-2.5 border border-slate-200 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:outline-none text-slate-700 text-sm"
            />
            <button 
              type="submit"
              className="px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg text-sm transition duration-200 shadow-sm whitespace-nowrap"
            >
              Add Task
            </button>
          </form>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50/50">
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-500">Tasks List</h2>
          </div>
          {data?.getTodos?.length === 0 ? (
            <div className="p-8 text-center text-slate-400 text-sm">No tasks yet. Add one above!</div>
          ) : (
            <ul className="divide-y divide-slate-100">
              {data?.getTodos?.map((item) => (
                <li key={item.id} className="p-4 flex items-center justify-between hover:bg-slate-50/50 transition">
                  <span className="text-slate-700 text-sm font-medium">{item.text}</span>
                  <button 
                    onClick={() => handleDeleteTodo(item.id)}
                    className="text-xs font-medium text-red-500 hover:text-red-700 px-3 py-1.5 rounded bg-red-50/50 hover:bg-red-50 transition"
                  >
                    Delete
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}
